#include <bits/stdc++.h>
using namespace std;const int N=30;unsigned long long a[N],b[N][61],c[61],t[61];int p[N],d[N],z[N][61];void I(unsigned long long*x,int*y,unsigned long long v,int k){for(int i=60;i>=0;i--)if(v>>i&1){if(!x[i]){x[i]=v;y[i]=k;return;}if(y[i]<k)swap(y[i],k),swap(x[i],v);v^=x[i];}}void J(unsigned long long*x,unsigned long long v){for(int i=60;i>=0;i--)if(v>>i&1){if(x[i])v^=x[i];else{x[i]=v;return;}}}int main(int C,char**v){ios::sync_with_stdio(0);cin.tie(0);int R=C>1?stoi(v[1]):1000;unsigned long long s=C>2?stoull(v[2]):1;mt19937_64 g(s);while(R--){int n=g()%20+1;memset(b,0,sizeof b);memset(z,0,sizeof z);d[1]=1;p[1]=0;for(int i=1;i<=n;i++){a[i]=g()%4096;if(i>1)p[i]=g()%(i-1)+1,d[i]=d[p[i]]+1;memcpy(b[i],b[p[i]],sizeof b[i]);memcpy(z[i],z[p[i]],sizeof z[i]);I(b[i],z[i],a[i],d[i]);}for(int Q=0;Q<20;Q++){int x=g()%n+1,y=g()%n+1,u=x,w=y;while(d[u]>d[w])u=p[u];while(d[w]>d[u])w=p[w];while(u!=w)u=p[u],w=p[w];int l=u;memset(c,0,sizeof c);for(int i=60;i>=0;i--){if(z[x][i]>=d[l])J(c,b[x][i]);if(z[y][i]>=d[l])J(c,b[y][i]);}unsigned long long A=0;for(int i=60;i>=0;i--)A=max(A,A^c[i]);memset(t,0,sizeof t);for(u=x;u!=l;u=p[u])J(t,a[u]);for(u=y;u!=l;u=p[u])J(t,a[u]);J(t,a[l]);unsigned long long B=0;for(int i=60;i>=0;i--)B=max(B,B^t[i]);if(A!=B)return cout<<"WA\n",1;}}cout<<"OK\n";}
